<?php require_once __DIR__ . '/../includes/functions.php'; admin_header('Dashboard'); $cards=['New Cases'=>'SELECT COUNT(*) c FROM patient_cases WHERE DATE(created_at)=CURDATE()','Pending Doctor Review'=>'SELECT COUNT(*) c FROM patient_cases WHERE doctor_status="pending"','Approved Prescriptions'=>'SELECT COUNT(*) c FROM prescriptions WHERE status="approved"','Pending Orders'=>'SELECT COUNT(*) c FROM orders WHERE status IN ("requested","pending_doctor_verification")','Delivered Orders'=>'SELECT COUNT(*) c FROM orders WHERE status="delivered"','Emergency Flagged Cases'=>'SELECT COUNT(*) c FROM patient_cases WHERE emergency_flag=1','Formula Candidates'=>'SELECT COUNT(*) c FROM formula_candidates WHERE review_status="pending"','AI Corrections'=>'SELECT COUNT(*) c FROM ai_corrections WHERE approved_for_learning=1']; ?><div class="row g-3"><?php foreach($cards as $label=>$sql): $n=db_fetch($sql)['c'] ?? 0; ?><div class="col-md-3"><div class="card soft-card metric"><div class="card-body"><p class="text-muted mb-1"><?= e($label) ?></p><h2><?= e((string)$n) ?></h2></div></div></div><?php endforeach; ?></div><?php admin_footer(); ?>
